export function TooltipDot({
  x,
  y,
  visible,
  color,
  size = 5,
  strokeColor = chartCssVars.background,
  strokeWidth = 2,
  variant = "dot",
  cornerRadiusFraction = 0.25,
  springConfig,
  animate = true,
}: TooltipDotProps) {
  const { tooltipSpring } = useChartConfig();
  const effectiveSpring = springConfig ?? tooltipSpring;
  const animatedX = useSpring(x, effectiveSpring);
  const animatedY = useSpring(y, effectiveSpring);

  const isRing = variant === "ring";
  const fill = isRing ? "transparent" : color;
  const stroke = isRing ? color : strokeColor;
  const effectiveStrokeWidth = isRing ? (strokeWidth ?? 1.5) : strokeWidth;

  if (animate && !isRing) {
    animatedX.set(x);
    animatedY.set(y);
  }

  if (!visible) {
    return null;
  }

  if (isRing) {
    if (animate) {
      return (
        <AnimatedRingDot
          cornerRadiusFraction={cornerRadiusFraction}
          fill={fill}
          halfExtent={size}
          springConfig={springConfig}
          stroke={stroke}
          strokeWidth={effectiveStrokeWidth}
          x={x}
          y={y}
        />
      );
    }

    const side = size * 2;
    const rx = ringCornerRadius(size, cornerRadiusFraction);

    return (
      <rect
        fill={fill}
        height={side}
        rx={rx}
        ry={rx}
        stroke={stroke}
        strokeWidth={effectiveStrokeWidth}
        width={side}
        x={x - size}
        y={y - size}
      />
    );
  }

  if (!animate) {
    return (
      <circle
        cx={x}
        cy={y}
        fill={fill}
        r={size}
        stroke={stroke}
        strokeWidth={effectiveStrokeWidth}
      />
    );
  }

  return (
    <motion.circle
      cx={animatedX}
      cy={animatedY}
      fill={fill}
      r={size}
      stroke={stroke}
      strokeWidth={effectiveStrokeWidth}
    />
  );
}

